/// 
/// complete_stream (Plan 022 follow-up, auto-lang Plan 397): takes an
/// `Arc<Fn(JsonValue)>` callback invoked per SSE event the daemon emits. The
/// real AiClient adapter (client_impl.rs) overrides it with true SSE streaming;
/// test mocks implement it via the `default_complete_stream` helper (a free fn
/// in client_impl.rs) since spec default bodies can't call self methods
/// (a2r DIV-TRAIT-A2R-3 known gap).
/// One non-streaming completion request.
/// Streaming completion. Calls `on_event` for each SSE event the daemon
/// emits (a JsonValue like {"type":"delta","text":"…"}). Returns the
/// accumulated full response on success.
/// Events emitted by Agent.run_stream as the ReAct loop progresses.
/// Tuple variants (plan 013 gotcha B3) — see file header for field order.
/// A chunk of the model's text output. (text)
/// A tool is about to be executed. (tool, args)
/// A non-fatal advisory message (e.g. the near-turn-cap warning). (text)
/// A tool was called and produced a result. (tool, args, result)
/// The loop finished successfully (carries the full result). (result)
/// The run was cancelled by the user. (result)
/// The loop failed. (message)
#[derive(Clone, Debug, PartialEq)]
pub enum StreamEvent {
    Delta(String),
    ToolStart(String, JsonValue),
    Warning(String),
    Tool(String, JsonValue, String),
    Done(AgentResult),
    Cancelled(AgentResult),
    Error(String),
}


struct EventSink {
    log: String,
    cb: Box<dyn Fn(StreamEvent) + Send + Sync>,
}

impl EventSink {
    pub fn new() -> Self {
        Self {
            log: format!(""),
            cb: Box::new(move |e: StreamEvent| { }),
        }
    }

    pub async fn start(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        Ok(())
    }

    pub async fn stop(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        Ok(())
    }

    pub async fn handle_msg(&mut self, msg: StreamEvent, reply_tx: a2r_std::task::NopReply) -> Result<(), Box<dyn std::error::Error>> {
        match msg {
            ev => {
                




                (self.cb)(ev.clone());
                match ev {
                    StreamEvent::Delta(text) => self.log = format!("{}D:{};", self.log, text),
                    StreamEvent::ToolStart(tool, _args) => self.log = format!("{}TS:{};", self.log, tool),
                    StreamEvent::Warning(text) => self.log = format!("{}W:{};", self.log, text),
                    StreamEvent::Tool(tool, _args, _result) => self.log = format!("{}T:{};", self.log, tool),
                    StreamEvent::Done(result) => self.log = format!("{}DONE:{};", self.log, result.output),
                    StreamEvent::Cancelled(result) => self.log = format!("{}CANCEL:{};", self.log, result.output),
                    StreamEvent::Error(message) => self.log = format!("{}E:{};", self.log, message),
                };
            }
            _ => {
                let _ = msg;
            }
        };
        Ok(())
    }
}

pub fn spawn_event_sink_with(log: String, cb: Box<dyn Fn(StreamEvent) + Send + Sync>) -> a2r_std::task::TaskRef<StreamEvent> {
    let (taskref, mut rx) = a2r_std::task::channel::<StreamEvent>();
    let join = tokio::spawn(async move {
        let mut actor = EventSink { log: log, cb: cb };
        let _ = actor.start().await;
        while let Some(msg) = rx.recv().await {
            let reply_tx = a2r_std::task::NopReply;
            let _ = actor.handle_msg(msg, reply_tx).await;
            rx.mark_processed();
        }
    });
    a2r_std::task::track_join(join);
    taskref
}

pub fn spawn_event_sink() -> a2r_std::task::TaskRef<StreamEvent> {
    let (taskref, mut rx) = a2r_std::task::channel::<StreamEvent>();
    let join = tokio::spawn(async move {
        let mut actor = EventSink::new();
        let _ = actor.start().await;
        while let Some(msg) = rx.recv().await {
            let reply_tx = a2r_std::task::NopReply;
            let _ = actor.handle_msg(msg, reply_tx).await;
            rx.mark_processed();
        }
    });
    a2r_std::task::track_join(join);
    taskref
}


