impl Agent {
    pub fn new_shared(role: Box<dyn Role>, client: Box<dyn Client>) -> Agent {
        let limit = role.memory_limit();
        return Agent { role: role, tools: ToolRegistry::new(), memory: Memory::new(limit), client: client, skills_block: None, context_block: None };
    }
    pub fn with_context(&mut self, context: &str) {
        let ctx = context.trim().to_string();
        if ctx.is_empty() == false {
            self.context_block = Some(context.to_string());
        }
    }
    pub fn register_shared(&mut self, tool: Arc<dyn Tool>) {
        self.tools.register_shared(tool);
    }
    pub fn register_tool(&mut self, tool: Box<dyn Tool>) {
        self.tools.register(tool);
    }
    pub fn register_skill_tool(&mut self, tool: SkillTool) {
        let block = tool.available_skills_block();
        match (block.len() as i32) == 0 {
            true => self.skills_block = None,
            false => self.skills_block = Some(block),
        };



        self.register_tool(Box::new(tool));
    }
    pub fn memory_messages(&self) -> Vec<Message> {
        return self.memory.messages();
    }
    pub fn history(&self) -> Vec<Message> {
        return self.memory.messages();
    }
    pub async fn run(&mut self, task_msg: &str) -> Result<AgentResult, AgentError> {

        let discard = spawn_event_sink();
        return self.run_inner(task_msg, None, discard).await;
    }
    pub async fn run_stream(&mut self, task_msg: &str, cancel: Arc<AtomicBool>, sink: a2r_std::task::TaskRef<StreamEvent>) -> Result<AgentResult, AgentError> {
        return self.run_inner(task_msg, Some(cancel), sink).await;
    }
    pub async fn run_inner(&mut self, task_msg: &str, cancel: Option<Arc<AtomicBool>>, sink: a2r_std::task::TaskRef<StreamEvent>) -> Result<AgentResult, AgentError> {
        self.memory.add("user", task_msg);
        let soft_limit = self.role.max_turns();
        let hard_limit: u32 = soft_limit * 5;
        let mut result = AgentResult::default();

        let mut seen: std::collections::HashMap<String, u32> = std::collections::HashMap::new();
        let mut seen_names: Vec<String> = vec![];

        let mut turn: u32 = 0 as u32;
        while turn < hard_limit {
            
            if is_cancelled(cancel.clone()) {
                let ce = cancelled_event(result.clone());
                sink.send(ce);
                return Ok(result);
            }
            turn = turn + 1;
            result.turns = turn;
            

            let remaining: u32 = hard_limit - turn;
            if remaining <= 5 {
                if remaining > 1 {
                    let w = StreamEvent::Warning(format!("{} turns until the hard stop — wrap up now.", remaining - 1));
                    sink.send(w);
                }            }
            
            let req = self.build_request();
            






            let sink_cb = sink.clone();
            let resp = self.client.complete_stream(req, Arc::new(move |ev| forward_sse_delta(ev.clone(), &sink_cb))).await?;
            

            if is_cancelled(cancel.clone()) {
                result.total_tokens = record_usage(result.clone(), resp.clone());
                let ce = cancelled_event(result.clone());
                sink.send(ce);
                return Ok(result);
            }
            

            match resp.error {
                Some(err) => {
                    

                    let ev = StreamEvent::Error(err.clone());
                    sink.send(ev);
                    return Err(AgentError::Config(err));
                },
                None => {},
            };
            result.total_tokens = record_usage(result.clone(), resp.clone());
            
            if resp.wants_tool() {
                

                if is_cancelled(cancel.clone()) {
                    let ce = cancelled_event(result.clone());
                    sink.send(ce);
                    return Ok(result);
                }                



                let mut blocks: Vec<ContentBlock> = vec![];
                if resp.content.is_empty() == false {
                    let tb = ContentBlock::Text { text: resp.content };
                    blocks.push(tb.clone());
                }                let mut tc_idx: u32 = 0 as u32;
                

                for tc in resp.tool_calls.clone() {
                    let ub = ContentBlock::ToolUse { id: tc.id, name: tc.name, input: tc.input };
                    blocks.push(ub.clone());
                    tc_idx = tc_idx + 1;
                }
                if blocks.is_empty() == false {
                    let am = Message { role: "assistant".to_string(), content: blocks };
                    self.memory.add_message(am);
                }                




                let mut keep_going: bool = true;
                for tc in resp.tool_calls.clone() {
                    let key: String = format!("{}::{}", tc.name, tc.input);
                    let count = bump_seen(seen.clone(), seen_names.clone(), key.as_str());
                    if count >= loop_detect_threshold() {
                        let ev = StreamEvent::Error(format!("loop detected on '{}'", tc.name));
                        sink.send(ev);
                        return Err(AgentError::LoopDetected(tc.name));
                    }
                    
                    let ts = StreamEvent::ToolStart(tc.name.clone(), tc.input.clone());
                    sink.send(ts);
                    
                    let outcome = self.tools.exec_or_msg(tc.name.as_str(), tc.input.clone()).await;
                    let rec = ToolCallRecord { tool: tc.name.clone().to_string(), args: tc.input.clone(), result: outcome.clone().to_string() };
                    result.tool_calls.push(rec.clone());
                    let tev = StreamEvent::Tool(tc.name, tc.input, outcome.clone());
                    sink.send(tev);
                    

                    let tr = Message::tool_result(tc.id, truncate_tool_result(outcome.as_str()));
                    self.memory.add_message(tr);
                }
                

            } else {
                

                result.output = resp.content.clone();
                

                self.memory.add("assistant", resp.content.as_str());
                let done = StreamEvent::Done(clone_result(result.clone()));
                sink.send(done);
                return Ok(result);
            }

        }


        let err = StreamEvent::Error(format!("hard turn cap ({}) exceeded (soft limit was {})", hard_limit, soft_limit));
        sink.send(err);
        return Err(AgentError::MaxTurnsExceeded(hard_limit));
    }
    pub fn build_request(&self) -> CompletionRequest {
        let allowed = self.role.allowed_tools();
        let visible = self.tools.filter(allowed);
        let mut tool_defs: Vec<ToolDefinition> = vec![];
        for t in &visible {
            tool_defs.push(tool_to_definition(t.clone()));
        }



        let pinned = self.role.model();
        let model = build_model_id(pinned.as_str(), self.role.model_tier());

        let system_prompt = build_system_prompt(self.context_block.clone(), self.role.system_prompt().as_str(), self.skills_block.clone());

        return CompletionRequest { model: model, messages: self.memory.to_messages(), max_tokens: None, temperature: Some(self.role.temperature()), system_prompt: Some(system_prompt), tools: tool_defs, stream: false, preferred_provider: self.role.preferred_provider() };
    }
}

